diurnalStress.formula:
DIURNAL TIDAL STRESS as f(angle-to-t_hat, phase). Synchronous moon, eccentric orbit, thin-shell/membrane (Beuthe 2016 'membrane paradigm' eq.146; IDENTICAL to Wahr et al. 2009 VGT surface stresses). Use the TIDAL frame anchored on t_hat: theta=colatitude from the t_hat pole, phi=longitude around t_hat (so t_hat is the sub-primary point). wt = n*t = orbital phase (mean anomaly); seed a frozen phase phi0 for the rendered snapshot. Tensile-positive:
  sigma_tt = (3/4)(n^2 R/g) e * Re{ [ -(b1+3 g1 cos2theta) + (b1 - g1 cos2theta)(3 cos2phi - 4 i f sin2phi) ] e^{i(wt)} }
  sigma_pp = (3/4)(n^2 R/g) e * Re{ [ -(b2+3 g2 cos2theta) + (b2 - g2 cos2theta)(3 cos2phi - 4 i f sin2phi) ] e^{i(wt)} }
  sigma_tp = -3 (n^2 R/g) e * Re{ [ g3 cos theta (3 sin2phi + 4 i f cos2phi) ] e^{i(wt)} }
with (b1,b2)=mu l2 (A+3, A-3); (g1,g2)=mu l2 (A-1, A+1); g3=mu l2; A=((1+nu)/(1-nu))(h2/l2 - 3) (Beuthe eqs.63-66). f=1 for pure eccentricity tide (f encodes libration). h2,l2=tidal Love numbers, mu=shell rigidity, e=eccentricity.
CODEABLE: fold (3/4)(n^2 R/g) e and the Love/rigidity constants into ONE seeded amplitude A_diur (per regime). Use illustrative b1=b2=g1=g2=g3=1, f=1, and a seeded eccentricity-proxy. Render ONE frozen phase phi0 (render-once; NO time loop). At each node compute theta=angle(d,t_hat), phi=longitude of d around t_hat, then evaluate the three Re{...} with wt=phi0 to get a,b,c contributions in the tidal-frame {theta,phi} basis, then rotate into the carrier {east,north} tangent frame before summing with despin.

stressSpec.buildReadyPseudocode:
// ============================================================================
// shellRelief.js -- despun / ice-shell / tidally-locked relief writer
// THREE-FREE, DETERMINISTic (all RNG via alea(seedString) off integer macroSeed),
// GENERATIVE-NOT-SIMULATIVE (one pass + bounded Jacobi relax; render-ONE frozen phase).
// Organizes relief about SEEDED paleo-spin axis w0 and SEEDED tidal axis t_hat.
// ============================================================================
import alea from 'alea';
import { createNoise3D } from 'simplex-noise';
import { clamp } from './mathutil.js';

const dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
function norm(a){const l=Math.hypot(a[0],a[1],a[2])||1;return[a[0]/l,a[1]/l,a[2]/l];}
function randDir(rng){const z=2*rng()-1,t=2*Math.PI*rng(),r=Math.sqrt(Math.max(0,1-z*z));return[r*Math.cos(t),r*Math.sin(t),z];}

export const REGIME={ICY_ACTIVE:0,VOLATILE_COLD:1,EYEBALL_DESPUN:2};
export const DEFAULTS=Object.freeze({
  DESPIN_REF:1.0, DIUR_REF:1.0, STRESS_TARGET:0.9,
  TENSILE_THRESH:0.05, CHAOS_THRESH:0.62, CREST_THRESH:0.62,
  RIDGE_FREQ:6.0, RIDGE_OCTAVES:4, RELAX_PASSES:4,
  RIDGE_DEPTH:0.18,   // central-trough depth of the double ridge
  SHOULDER_HT:0.10,   // height of each flanking shoulder
  W:{ // per-regime [w_despin, w_diur]
    0:[1.0,1.0], 1:[1.0,0.15], 2:[1.0,0.0] }
});

// ---- per-regime stress weights ----
export function writeShellRelief(carrier, drivers={}, {macroSeed=0, regime=0}={}){
  const T=DEFAULTS, N=carrier.N, verts=carrier.verts, adj=carrier.adj;
  const seed=macroSeed|0;
  const [wDespin,wDiur]=T.W[regime];

  // --- SEED the two axes + amplitudes + frozen orbital phase (NO Math.random/Date.now) ---
  const rAxis=alea('shell:axis:'+seed);
  const w0   = randDir(rAxis);                 // paleo-spin axis
  const tHat = norm(cross(w0, randDir(rAxis)));// tidal axis (seeded, not forced orthogonal-only)
  const eHat = norm(cross(w0, tHat));          // tidal-frame east reference
  const A_despin = T.DESPIN_REF*(0.6+0.8*alea('shell:despin:'+seed)());
  const A_diur   = T.DIUR_REF  *(0.6+0.8*alea('shell:diur:'  +seed)());
  const phi0     = 2*Math.PI*alea('shell:phase:'+seed)();   // frozen orbital phase (render-once)
  const ridgeNoise=createNoise3D(alea('shell:ridge:'+seed));

  const sigma1   = new Float32Array(N);   // SIGNED max-tensile (raw, pre-normalize)
  const thetaTraj= new Float32Array(N);   // most-tensile principal-axis angle in {east,north}
  const tmpE=new Float32Array(N), tmpN=new Float32Array(N);

  // ===========================================================================
  // STEP 1 -- build + sum + diagonalize the 2x2 surface stress tensor per node
  // ===========================================================================
  for(let i=0;i<N;i++){
    const d=verts[i];
    const {east,north}=carrier.tangentFrameAt(d); // orthonormal tangent basis at d

    // ---- (1a) DESPIN tensor in {theta_w0, phi_w0}, diagonal (no shear) ----
    const cw=clamp(-1,1,dot(d,w0));
    const thW=Math.acos(cw);                 // colatitude from w0
    const mu=Math.cos(2*thW);
    const s_thetaW = A_despin*(3*mu+5)/6;     // meridional  (tensile everywhere)
    const s_phiW   = A_despin*(9*mu-1)/6;     // azimuthal   (tensile poles, compr equator)
    // direction of phi_hat(w0) = (w0 x d) normalized; theta_hat(w0) = phi_hat x d
    let phiW=norm(cross(w0,d)); if(!isFinite(phiW[0])) phiW=east;
    const thetaW=norm(cross(phiW,d));
    // tensor in world-tangent: M_d = s_thetaW*(thetaW⊗thetaW)+s_phiW*(phiW⊗phiW)
    // project onto {east,north} -> aD,bD,cD
    const pT=[dot(thetaW,east),dot(thetaW,north)], pP=[dot(phiW,east),dot(phiW,north)];
    let aD=s_thetaW*pT[0]*pT[0]+s_phiW*pP[0]*pP[0];
    let bD=s_thetaW*pT[0]*pT[1]+s_phiW*pP[0]*pP[1];
    let cD=s_thetaW*pT[1]*pT[1]+s_phiW*pP[1]*pP[1];

    // ---- (1b) DIURNAL tensor in {theta_t, phi_t}, has SHEAR (drives rotation) ----
    let aT=0,bT=0,cT=0;
    if(wDiur>0){
      const ct=clamp(-1,1,dot(d,tHat));
      const thT=Math.acos(ct);                // colatitude from tHat
      // longitude phi around tHat measured from eHat
      const dp=[d[0]-ct*tHat[0],d[1]-ct*tHat[1],d[2]-ct*tHat[2]];
      const ph=Math.atan2(dot(dp,cross(tHat,eHat)),dot(dp,eHat));
      const c2t=Math.cos(2*thT), wt=phi0, f=1.0;
      // membrane eq.146 real parts (b1=b2=g1=g2=g3=1 illustrative); Re{ S e^{i wt} }
      const modR=3*Math.cos(2*ph), modI=-4*f*Math.sin(2*ph);
      const Stt_r=-(1+3*c2t)+(1-c2t)*modR, Stt_i=(1-c2t)*modI;
      const Spp_r=Stt_r, Spp_i=Stt_i; // equal here; differ once b1!=b2 etc.
      const Stp_r=-(Math.cos(thT))*(3*Math.sin(2*ph)), Stp_i=-(Math.cos(thT))*(4*f*Math.cos(2*ph));
      const s_tt=Stt_r*Math.cos(wt)-Stt_i*Math.sin(wt);
      const s_pp=Spp_r*Math.cos(wt)-Spp_i*Math.sin(wt);
      const s_tp=Stp_r*Math.cos(wt)-Stp_i*Math.sin(wt);
      // tidal-frame directions -> {east,north}
      let phiT=norm(cross(tHat,d)); if(!isFinite(phiT[0])) phiT=east;
      const thetaT=norm(cross(phiT,d));
      const qT=[dot(thetaT,east),dot(thetaT,north)], qP=[dot(phiT,east),dot(phiT,north)];
      // M = s_tt*(thetaT⊗thetaT)+s_pp*(phiT⊗phiT)+s_tp*(thetaT⊗phiT+phiT⊗thetaT)
      aT=A_diur*(s_tt*qT[0]*qT[0]+s_pp*qP[0]*qP[0]+2*s_tp*qT[0]*qP[0]);
      bT=A_diur*(s_tt*qT[0]*qT[1]+s_pp*qP[0]*qP[1]+s_tp*(qT[0]*qP[1]+qP[0]*qT[1]));
      cT=A_diur*(s_tt*qT[1]*qT[1]+s_pp*qP[1]*qP[1]+2*s_tp*qT[1]*qP[1]);
    }

    // ---- (1c) SUM tensors ----
    const a=wDespin*aD+wDiur*aT, b=wDespin*bD+wDiur*bT, c=wDespin*cD+wDiur*cT;

    // ---- (1d) DIAGONALIZE (verified) ----
    const mean=(a+c)/2, rad=Math.hypot((a-c)/2,b);
    const lamMax=mean+rad;                      // SIGNED max-tensile = sigma1
    let th=0.5*Math.atan2(2*b, a-c);            // axis of lamMax (load-bearing arg order)
    // sign guard: ensure th maximizes Rayleigh quotient (else +90deg)
    const cs=Math.cos(th), sn=Math.sin(th);
    const rq=a*cs*cs+2*b*cs*sn+c*sn*sn;
    if(rq < mean) th+=Math.PI/2;
    sigma1[i]=lamMax; thetaTraj[i]=th;
  }

  // ---- NORMALIZE sigma1 into ~[-1,1] (empirical-deterministic STRESS_REF) ----
  let maxAbs=1e-9; for(let i=0;i<N;i++) maxAbs=Math.max(maxAbs,Math.abs(sigma1[i]));
  const STRESS_REF=maxAbs/T.STRESS_TARGET;
  const sigma1n=new Float32Array(N);
  for(let i=0;i<N;i++) sigma1n[i]=clamp(-1,1,sigma1[i]/STRESS_REF);

  // ===========================================================================
  // STEP 3 -- steer ridged field along thetaTraj, gate by sigma1, derive
  //           lineamentNode, write analytic DOUBLE-RIDGE cross-section.
  // ===========================================================================
  const R=new Float32Array(N);            // steered ridged field in [0,1]
  const lineamentNode=new Uint8Array(N);
  const height=new Float32Array(N);
  for(let i=0;i<N;i++){
    const d=verts[i];
    const {east,north}=carrier.tangentFrameAt(d);
    // steering: sample noise on a coordinate that advances ACROSS theta_traj so ridge
    // lines run ALONG theta_traj. u = position projected onto the cross-crack normal.
    const th=thetaTraj[i];
    const nrm=[ // crack-normal direction in 3D = -sin(th)*east + cos(th)*north
      -Math.sin(th)*east[0]+Math.cos(th)*north[0],
      -Math.sin(th)*east[1]+Math.cos(th)*north[1],
      -Math.sin(th)*east[2]+Math.cos(th)*north[2]];
    // ridged multifractal sampled along the crack-normal gives lines parallel to theta_traj
    let amp=1,freq=T.RIDGE_FREQ,sum=0,normf=0;
    for(let o=0;o<T.RIDGE_OCTAVES;o++){
      const p=[d[0]*freq+nrm[0],d[1]*freq+nrm[1],d[2]*freq+nrm[2]];
      const n=ridgeNoise(p[0],p[1],p[2]);
      const ridge=1-Math.abs(n);            // ridged transform -> sharp ridge lines
      sum+=amp*ridge*ridge; normf+=amp; amp*=0.5; freq*=2.0;
    }
    R[i]=sum/normf;                         // in [0,1]

    // CREST RULE: absolute threshold gated by tensile stress (NOT local-max)
    const tensile = sigma1n[i] > T.TENSILE_THRESH;
    const crest   = R[i] > T.CREST_THRESH;
    lineamentNode[i] = (tensile && crest) ? 1 : 0;

    // ANALYTIC DOUBLE-RIDGE cross-section: central trough flanked by two shoulders.
    // s = signed distance across the crack within the ridge band, in [-1,1]:
    //   model the band by how far R[i] sits above CREST_THRESH (0 at edge -> 1 at ridge center)
    let h=0;
    if(lineamentNode[i]){
      const band=clamp(0,1,(R[i]-T.CREST_THRESH)/(1-T.CREST_THRESH)); // 0..1 across band
      // s in [-1,1]: re-center so band edge -> |s|=1, ridge center -> s=0
      const s=1-band;                    // 0 at center, 1 at edges (approx within graph)
      // double-ridge: trough at center, positive shoulders at |s|~0.5, flat at edges.
      // analytic: h(s) = SHOULDER_HT*(1 - (2*s-1)^2 ... ) ; use the canonical form:
      //   trough  = -RIDGE_DEPTH * exp(-(s/0.25)^2)              (narrow central low)
      //   shoulder=  SHOULDER_HT * exp(-((|s|-0.5)/0.22)^2)      (two flanking highs)
      const trough = -T.RIDGE_DEPTH*Math.exp(-(s/0.25)*(s/0.25));
      const shoulder= T.SHOULDER_HT*Math.exp(-((Math.abs(s)-0.5)/0.22)**2);
      h = trough + shoulder;             // central trough flanked by two positive shoulders
      // scale by tensile stress so stronger-tension cracks are deeper/sharper
      h *= clamp(0,1, sigma1n[i]);
    }
    height[i]=h;
  }

  // ---- bounded gen-time Jacobi relax (render-once; convex combo, cannot grow bound) ----
  const buf=new Float32Array(N);
  for(let pass=0;pass<T.RELAX_PASSES;pass++){
    for(let i=0;i<N;i++){let sum=height[i],cnt=1;const nb=adj[i];
      for(let k=0;k<nb.length;k++){sum+=height[nb[k]];cnt++;}
      buf[i]=height[i]*0.5+(sum/cnt)*0.5;}
    height.set(buf);
  }

  // ---- WRITE carrier (REPLACE height; grainAngle = steering axis; faultDensity = tensile activity) ----
  carrier.height.set(height);
  for(let i=0;i<N;i++){ carrier.grainAngle[i]=thetaTraj[i]; carrier.faultDensity[i]=Math.max(0,sigma1n[i]); }

  return {sigma1, sigma1n, thetaTraj, R, lineamentNode, w0, tHat, phi0, STRESS_REF, A_despin, A_diur, regime, relaxPasses:T.RELAX_PASSES};
}
